def model2(p,t,P):
    return p[0]*np.log(1+p[1]*P)*t + p[2]*np.tanh(p[3]*t) + p[4]*np.tanh(p[5]*t)*P**3 + p[6]*P**2 + p[7]*P
best=None
for s in range(30):
    x0=np.r_[np.random.rand(1)*2, np.random.rand(1)*0.5+0.1, np.random.randn(1)*5, np.random.rand(1)*0.5, np.random.randn(1)*0.1, np.random.rand(1)*1, np.random.randn(1)*0.2, np.random.randn(1)*0.1]
    try:
        r=least_squares(lambda p: model2(p,t,P)-dP_dt, x0)
    except Exception: continue
    if np.isfinite(r.cost) and (best is None or r.cost<best.cost): best=r
print(best.x, best.cost, "NMSE", 2*best.cost/np.sum((dP_dt-dP_dt.mean())**2))
